SOURCE_CLAIM_JSON: {"title":"Pemerintah Perkuat Kebijakan Satu Data dengan Registrasi Sosial Ekonomi","publisher":"Sekretariat Kabinet Republik Indonesia","publication_date":"2022-10-12","url":"https://setkab.go.id/pemerintah-perkuat-kebijakan-satu-data-dengan-registrasi-sosial-ekonomi/","claim":"Jokowi said strengthening one-data policy through Regsosek 2022 was necessary so the census could cover all residents, and the government asked BPS to run national data collection and update separated welfare datasets.","locator":"lines 46-57","source_type":"official","source_confidence":"high","source_confidence_reason":"Direct presidential-meeting recap with named presidential instruction and implementation details.","final_evidence_use":"final_evidence","period_fit":"Direct 2022 ruler action on social-registry targeting.","ruler_attribution":"Directly attributable to Jokowi as the president who chaired the meeting and issued the instruction; execution ran through BPS and coordinating ministries.","contrary_evidence":["This is a targeting/infrastructure measure, not proof of downstream welfare gains.","The page reports intent and data integration, not full nationwide completion."],"lenses":["6B.1","6B.3","6B.4","6B.5","6B.7","6B.9"]}
SOURCE_CLAIM_JSON: {"title":"The social and economic impact of COVID-19 on households in Indonesia","publisher":"UNICEF Indonesia","publication_date":"2022-08","url":"https://www.unicef.org/indonesia/reports/social-and-economic-impact-covid-19-households-indonesia","claim":"A second survey conducted in February-March 2022 at the request of the Indonesian Ministry of Finance captured longitudinal data from 10,922 households and examined benefits and gaps in social protection, with special focus on children, women, people with disability, and vulnerable communities.","locator":"lines 64-66","source_type":"NGO","source_confidence":"high","source_confidence_reason":"Independent survey summary from UNICEF with explicit methodology, sample size, and policy focus.","final_evidence_use":"final_evidence","period_fit":"Direct 2022 household evidence with pandemic-era policy relevance.","ruler_attribution":"Government-requested survey under Jokowi’s administration, but the findings are diagnostic rather than direct presidential action.","contrary_evidence":["This is a survey, not an evaluation of causality for specific programs.","It highlights social-protection gaps as well as protections."],"lenses":["6B.3","6B.5","6B.6","6B.8","6B.10"]}
SOURCE_CLAIM_JSON: {"title":"Penyaluran BLT BBM Capai 95,9 Persen","publisher":"Sekretariat Kabinet Republik Indonesia","publication_date":"2022-09-27","url":"https://setkab.go.id/penyaluran-blt-bbm-capai-959-persen/","claim":"Jokowi said the BLT BBM disbursement had reached 95.9 percent, or 19.7 million beneficiaries, and that the BSU had reached 48.3 percent; the government framed both as social assistance to maintain purchasing power during the fuel-subsidy transfer.","locator":"lines 46-50","source_type":"official","source_confidence":"high","source_confidence_reason":"Direct presidential visit report with exact rollout figures and stated purpose.","final_evidence_use":"final_evidence","period_fit":"Direct September 2022 shock-response implementation.","ruler_attribution":"Directly attributable to Jokowi and his government as the public face of the rollout.","contrary_evidence":["Reported coverage is administrative rollout, not independent impact evaluation.","The policy responded to a fuel-price increase and household pressure."],"lenses":["6B.2","6B.6","6B.7","6B.10"]}
SOURCE_CLAIM_JSON: {"title":"Untuk Melindungi Masyarakat Miskin dan Rentan Miskin, Pemerintah Alokasikan Dana BLT BBM Rp24,17 Triliun","publisher":"Kementerian Keuangan Republik Indonesia","publication_date":"2022-09-19","url":"https://www.kemenkeu.go.id/informasi-publik/publikasi/berita-utama/BLT-BBM","claim":"The finance ministry said the fuel-subsidy transfer package totaled Rp24.17 trillion, including BSU for 14.6 million workers and BLT BBM for 20.65 million beneficiary families, plus local-government spending for social protection, jobs, and transport support.","locator":"opening paragraphs / ministerial remarks in the article","source_type":"official","source_confidence":"high","source_confidence_reason":"Official finance-ministry release with concrete fiscal and beneficiary figures.","final_evidence_use":"final_evidence","period_fit":"Direct 2022 fiscal response to the fuel-price shock.","ruler_attribution":"Government-level attribution under Jokowi’s administration through the finance ministry.","contrary_evidence":["The ministry’s own framing is promotional and not an independent impact evaluation.","The package was reactive to an adverse price shock rather than a standalone welfare expansion."],"lenses":["6B.2","6B.3","6B.6","6B.7","6B.10"]}
